{
  "up": "Select molecule_chembl_id as compound_chembl_id, canonical_smiles from molecule_dictionary join activities on molecule_dictionary.molregno = activities.molregno join assays on activities.assay_id = assays.assay_id join target_dictionary on assays.tid = target_dictionary.tid join compound_structures on molecule_dictionary.molregno = compound_structures.molregno where target_dictionary.pref_name = 'lethal malignant brain tumor-like protein 1' and target_dictionary.organism = 'Homo sapiens' order by compound_chembl_id"
}
